// Records `src/codepage-sqlserver-encodings.ts` from SQL Server: how it
// encodes the characters that Windows' tables (`src/codepage-tables.ts` and
// `src/codepage-encoding-overrides.ts`, generated by
// `npm run generate:codepages`) do not cover.
//
// Usage: npm run build && npm run record:codepages -- [--check]
//
// Connects with the configuration in `~/.tedious/test-connection.json`, as the
// integration tests do, and creates (and drops) a database named
// `__tedious_codepages` for each collation. Use SQL Server on Linux or on a
// current version of Windows: on older versions of Windows, SQL Server lacks
// some best fits (see the header of the generated file). With `--check`,
// writes nothing, but fails if the file is not what SQL Server gives.

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');

const { Connection, Request } = require('../lib/tedious');
const { buildEncodingTable } = require('../lib/text-encoding');
const { formatOverrides } = require('./generate-codepage-tables');
const { COLLATIONS, SQL_SERVER_ENCODINGS_QUERY, quoteName } = require('./codepage-collations');

const DATABASE = '__tedious_codepages';

const HEADER = `// Do not edit: recorded by \`npm run record:codepages\`
// (\`scripts/record-sqlserver-encodings.js\`) from SQL Server's own conversion of
// every character from U+0000 to U+FFFF to \`varchar\` in a database of each
// collation.
//
// How SQL Server encodes the characters that Windows' tables in
// \`codepage-encoding-overrides.ts\` do not cover. These are:
//
// - all the best-fit mappings of CP437 and CP850, for which the Unicode
//   Consortium publishes no encoding tables (only the tables to decode them).
// - best fits that newer versions of Windows (such as Windows Server 2022)
//   have and the published tables do not: 28 spaces, dashes, quotes and primes
//   from U+2000 to U+2036, U+2044, U+20A4 and U+2236 (10 to 27 of them in each
//   single-byte code page), and U+3099 and U+309A in CP932. SQL Server uses
//   them on Linux and on those versions of Windows. On older versions of
//   Windows, it encodes the single-byte ones as "?" instead.
//
// They are applied after \`ENCODING_OVERRIDES\`, and in the same format.

export const SQL_SERVER_ENCODINGS: { readonly [codepage: string]: string } = {
`;

function connect() {
  const { config } = JSON.parse(fs.readFileSync(path.join(os.homedir(), '.tedious', 'test-connection.json'), 'utf8'));
  return new Promise((resolve, reject) => {
    const connection = new Connection(config);
    connection.connect((err) => (err ? reject(err) : resolve(connection)));
  });
}

function execSql(connection, sql) {
  return new Promise((resolve, reject) => {
    const rows = [];
    const request = new Request(sql, (err) => (err ? reject(err) : resolve(rows)));
    request.on('row', (columns) => rows.push(columns.map((column) => column.value)));
    connection.execSql(request);
  });
}

async function main() {
  const check = process.argv.includes('--check');
  const connection = await connect();
  const [[originalDatabase]] = await execSql(connection, 'SELECT DB_NAME()');

  const entries = [];
  try {
    for (const [codepage, collation] of COLLATIONS) {
      await execSql(connection, `USE ${quoteName(originalDatabase)}; DROP DATABASE IF EXISTS ${DATABASE}`);
      await execSql(connection, `CREATE DATABASE ${DATABASE} COLLATE ${collation}`);
      await execSql(connection, `USE ${DATABASE}`);

      const rows = await execSql(connection, SQL_SERVER_ENCODINGS_QUERY);

      // How tedious encodes each UTF-16 code unit without these encodings.
      const { codes } = buildEncodingTable(codepage, false);
      const differences = [];
      for (const [v, bytes] of rows) {
        const char = Number(v);
        if (bytes.length > 2 || bytes.length === 0) {
          throw new Error(`${codepage}: U+${char.toString(16)} is encoded as ${bytes.toString('hex')}`);
        }
        const code = bytes.length === 2 ? (bytes[0] << 8) | bytes[1] : bytes[0];
        if (code !== codes[char]) {
          differences.push([char, code]);
        }
      }
      differences.sort((a, b) => a[0] - b[0]);

      if (differences.length > 0) {
        entries.push(`  ${codepage}:\n${formatOverrides(differences)}`);
      }
    }
  } finally {
    await execSql(connection, `USE ${quoteName(originalDatabase)}; DROP DATABASE IF EXISTS ${DATABASE}`);
    connection.close();
  }

  const content = HEADER + entries.join(',\n') + '\n};\n';
  const target = path.join(__dirname, '..', 'src', 'codepage-sqlserver-encodings.ts');
  if (!check) {
    fs.writeFileSync(target, content);
  } else if (fs.readFileSync(target, 'utf8') !== content) {
    console.error('src/codepage-sqlserver-encodings.ts is not what SQL Server gives.');
    process.exitCode = 1;
  }
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
